const results = [];
const seen = new Set();

for (const item of items) {
  const output = item.json.output || [];

  for (const block of output) {
    if (block.type === 'message' && Array.isArray(block.content)) {
      for (const content of block.content) {
        const annotations = content.annotations || [];
        for (const ann of annotations) {
          if (ann.type === 'url_citation' && ann.url) {
            if (!seen.has(ann.url)) {
              seen.add(ann.url);
              results.push({
                json: {
                  title: ann.title || null,
                  url: ann.url
                }
              });
            }
          }
        }
      }
    }
  }
}

return results;

function extractAll(regex, html) {
  const res = [];
  let m;
  while ((m = regex.exec(html)) !== null) {
    const text = m[1]
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    if (text) res.push(text);
  }
  return res;
}

return items.map(item => {
  const html = item.json.data || '';
  if (!html) {
    return { json: { error: 'empty_html' } };
  }

  const title =
    html.match(/<title[^>]*>(.*?)<\/title>/i)?.[1]?.trim() || null;

  const description =
    html.match(/<meta\s+name=["']description["']\s+content=["'](.*?)["']/i)?.[1] || null;

  const lang =
    html.match(/<html[^>]+lang=["'](.*?)["']/i)?.[1] || null;

  const h1 =
    html.match(/<h1[^>]*>(.*?)<\/h1>/i)?.[1]
      ?.replace(/<[^>]+>/g, ' ')
      .trim() || null;

  const h2 = extractAll(/<h2[^>]*>(.*?)<\/h2>/gi, html);
  const h3 = extractAll(/<h3[^>]*>(.*?)<\/h3>/gi, html);
  const h4 = extractAll(/<h4[^>]*>(.*?)<\/h4>/gi, html);

  const cta = extractAll(
    /<(a|button)[^>]*(href=["'](.*?)["'])?[^>]*>(.*?)<\/(a|button)>/gi,
    html
  );

  const lower = html.toLowerCase();

  return {
    json: {
      title,
      description,
      lang,
      h1,
      h2,
      h3,
      h4
    }
  };
});

const raw = $input.first().json.message?.content || "";

const lines = raw
  .split("\n")
  .map(l => l.trim())
  .filter(l => l && l.includes(" | "));

// только строки с РОВНО одним " | "
const valid = lines.filter(l => (l.match(/ \| /g) || []).length === 1);

// парсинг
let segments = valid.map(l => {
  const [segment, description] = l.split(" | ").map(s => s.trim());
  return { segment, description };
});

// дедуп по имени сегмента (без регистра)
const seen = new Set();
segments = segments.filter(x => {
  const k = (x.segment || "").toLowerCase();
  if (!k || seen.has(k)) return false;
  seen.add(k);
  return true;
});

return [{ json: { segments, count: segments.length } }];

// Берём URL продукта из ноды Code24
const product = $("Code24").first().json.clean_url || "Unknown Product";

// Массив сегментов из текущего item
const segs = $json.segments || [];

// Размножаем на отдельные строки для Google Sheets
const rows = segs
  .filter(s => s.segment && s.description)
  .map(s => ({
    json: {
      Product: product,
      Segment: s.segment,
      Description: s.description,
    }
  }));

// Если сегментов нет — всё равно вернём одну строку, чтобы не упала цепочка
if (rows.length === 0) {
  return [{ json: { Product: product, Segment: null, Description: null } }];
}

return rows;

// n8n Function node
// Input item fields expected:
// Reference, Segment, ICP, Interview, Pain map, JTBD, Value proposition
// Output: wide rows per each JTBD with all columns filled.

function safeParse(maybeStr) {
  if (maybeStr == null) return null;
  if (typeof maybeStr === 'object') return maybeStr;
  if (typeof maybeStr !== 'string') return null;
  let s = maybeStr.trim();

  // strip code fences if any
  if (s.startsWith("```")) {
    const i = s.indexOf("{");
    const j = s.lastIndexOf("}");
    if (i >= 0 && j >= 0) s = s.slice(i, j + 1);
  }
  // try as-is, then trimmed again
  try { return JSON.parse(s); } catch(e) {}
  try { return JSON.parse(s.replace(/\u00A0/g, " ").trim()); } catch(e2) { return null; }
}

function joinArr(x) {
  if (!x) return null;
  if (Array.isArray(x)) return x.map(v => (v == null ? "" : String(v))).map(v => v.trim()).filter(Boolean).join(" | ");
  // if it is object, stringify stable
  if (typeof x === "object") {
    try { return JSON.stringify(x); } catch(e) { return String(x); }
  }
  return String(x);
}

function get(obj, path, fallback = null) {
  try {
    return path.split(".").reduce((a, k) => (a && a[k] !== undefined ? a[k] : null), obj) ?? fallback;
  } catch (e) { return fallback; }
}

const out = [];

for (const item of $input.all()) {
  const ref = item.json["Reference"] ?? null;
  const segText = item.json["Segment"] ?? null;        // plain text list (may be multiline)
  const icp = item.json["ICP"] ?? null;
  const interview = item.json["Interview"] ?? null;

  const painMapRaw = item.json["Pain map"] ?? null;
  const jtbdRaw    = item.json["JTBD"] ?? null;
  const vpcRaw     = item.json["Value proposition"] ?? null;

  const painMap = safeParse(painMapRaw);
  const jtbd    = safeParse(jtbdRaw);
  const vpc     = safeParse(vpcRaw);

  // extract VPC bits
  const vpcProduct = get(vpc, "product");
  const vpcSegment = get(vpc, "segment");

  const vpcGains = get(vpc, "customer_profile.gains", []);
  const vpcPains = get(vpc, "customer_profile.pains", []);
  const vpcJobsF = get(vpc, "customer_profile.customer_jobs.functional", []);
  const vpcJobsS = get(vpc, "customer_profile.customer_jobs.social", []);
  const vpcJobsE = get(vpc, "customer_profile.customer_jobs.emotional", []);
  const vpcProducts = get(vpc, "value_map.products_services", []);
  const vpcPainRelievers = get(vpc, "value_map.pain_relievers", []);
  const vpcGainCreators = get(vpc, "value_map.gain_creators", []);

  // extract Pain map bits
  const pmSegment = get(painMap, "segment");
  const pmPains = Array.isArray(get(painMap, "pains")) ? painMap.pains : [];
  const pmPainTexts = pmPains.map(p => p && p.pain).filter(Boolean);

  // JTBD list
  const jtbdSegment = get(jtbd, "segment");
  const jtbdList = Array.isArray(get(jtbd, "jtbd")) ? jtbd.jtbd : [];

  // choose segment resolution priority: jtbd > vpc > painMap > plain Segment
  const resolvedSegment = jtbdSegment || vpcSegment || pmSegment || (typeof segText === "string" ? segText.split("\n")[0] : segText) || null;

  // if no JTBD at all, still return one diagnostic row so pipeline does not look empty
  if (jtbdList.length === 0) {
    out.push({
      json: {
        index: null,
        role: null,
        finish_reason: null,

        reference: ref,
        icp,
        interview,
        pain_map: painMapRaw,
        product: vpcProduct ?? null,
        segment: resolvedSegment,

        jtbd_job_statement: null,
        jtbd_situation: null,
        jtbd_struggle: null,
        jtbd_priority_score: null,

        // atom selection
        atom_category: "diagnostic",
        atom_index: 0,

        // wide fields fully filled from VPC / Pain map
        pain: joinArr(pmPainTexts.length ? pmPainTexts : vpcPains),
        gain: joinArr(vpcGains),
        customer_job: joinArr([...(vpcJobsF||[]), ...(vpcJobsS||[]), ...(vpcJobsE||[])]),
        customer_job_type: ["functional", "social", "emotional"].filter(t => (t==="functional" && (vpcJobsF||[]).length) || (t==="social" && (vpcJobsS||[]).length) || (t==="emotional" && (vpcJobsE||[]).length)).join(" | ") || null,
        product_service: joinArr(vpcProducts),
        pain_reliever: joinArr(vpcPainRelievers),
        gain_creator: joinArr(vpcGainCreators),

        desired_outcome: null,
        force_push: null,
        force_pull: null,
        force_anxiety: null,
        force_habit: null,
        acceptance_criteria: null,
        related_quote: null,
        moment_of_progress: null,
      }
    });
    continue;
  }

  // emit wide rows per JTBD, filling all columns
  jtbdList.forEach((j, jIndex) => {
    const forces = j && j.forces ? j.forces : {};
    const row = {
      index: item.json.index ?? null,
      role: item.json.role ?? null,
      finish_reason: item.json.finish_reason ?? null,

      reference: ref,
      icp,
      interview,
      pain_map: painMapRaw,
      product: vpcProduct ?? null,
      segment: resolvedSegment,

      jtbd_job_statement: j && j.job_statement != null ? String(j.job_statement) : null,
      jtbd_situation: j && j.situation != null ? String(j.situation) : null,
      jtbd_struggle: j && j.struggle != null ? String(j.struggle) : null,
      jtbd_priority_score: j && j.priority_score != null ? j.priority_score : null,

      atom_category: "jtbd",
      atom_index: jIndex,

      // fill with ALL known VPC/Pain map context (same for each JTBD row)
      pain: joinArr(pmPainTexts.length ? pmPainTexts : vpcPains),
      gain: joinArr(vpcGains),
      customer_job: joinArr([...(vpcJobsF||[]), ...(vpcJobsS||[]), ...(vpcJobsE||[])]),
      customer_job_type: ["functional", "social", "emotional"].filter(t => (t==="functional" && (vpcJobsF||[]).length) || (t==="social" && (vpcJobsS||[]).length) || (t==="emotional" && (vpcJobsE||[]).length)).join(" | ") || null,
      product_service: joinArr(vpcProducts),
      pain_reliever: joinArr(vpcPainRelievers),
      gain_creator: joinArr(vpcGainCreators),

      // JTBD atoms (per-row specifics)
      desired_outcome: joinArr(j && j.desired_outcomes),
      force_push: joinArr(forces.pushes),
      force_pull: joinArr(forces.pulls),
      force_anxiety: joinArr(forces.anxieties),
      force_habit: joinArr(forces.habits),
      acceptance_criteria: joinArr(j && j.acceptance_criteria),
      related_quote: joinArr(j && j.related_quotes),
      moment_of_progress: j && j.moment_of_progress != null ? String(j.moment_of_progress) : null,
    };

    out.push({ json: row });
  });
}

return out;

